import SwiftUI
struct SettingsView: View { @State private var theme = 0; let themes=["Graphite","Ivory","Midnight","Sage"]
 var body: some View { ScrollView{VStack(alignment:.leading,spacing:22){Text("الإعدادات").font(.largeTitle.bold());Text("السمة").font(.headline);HStack{ForEach(themes.indices,id:\.self){i in Button{theme=i}{VStack{Circle().fill(i == 0 ? Color.gray : i == 1 ? Color(red:0.84,green:0.78,blue:0.66) : i == 2 ? Color.indigo : Color.green.opacity(0.6)).frame(width:48,height:48).overlay(Circle().stroke(theme==i ? Color.white:.clear,lineWidth:2));Text(themes[i]).font(.caption2)}.foregroundStyle(.white)}};Divider().overlay(Color.white.opacity(0.1));Group{setting("لغة الواجهة","العربية");setting("تصدير افتراضي","PNG عالي الدقة");setting("العلامة المائية","جلاء");setting("الحركة","ناعمة")}}.padding(20).padding(.bottom,120)}}
 private func setting(_ a:String,_ b:String)->some View{HStack{Text(a);Spacer();Text(b).foregroundStyle(.white.opacity(0.45));Image(systemName:"chevron.left").foregroundStyle(.white.opacity(0.25))}.padding(.vertical,9)} }
